import logging


class BackgroundCmdRegistryEmpty(Exception):
    """BackgroundCmdRegistryEmpty exception"""
    pass


class BackgroundCmdRegistry(object):
    """Class to keep ExecuteCmdInBackground objects."""

    def __init__(self):
        """Creates registry"""
        self.background_cmd_registry = {}

    def register_cmd(self, name, background_cmd_instance):
        """
        Register new background cmd
        :param name: Name of background cmd instance
        :param background_cmd_instance: instance of ExecuteCmdInBackground class
        """
        self.background_cmd_registry[name] = background_cmd_instance
        logging.info('Adding new background cmd instance: {}'.format(name))

    def get_background_cmd(self, name):
        """
        Return background cmd instance from registry
        :param name: name of background cmd instance
        :return: instance of ExecuteCmdInBackground
        """
        if not self.background_cmd_registry:
            raise BackgroundCmdRegistryEmpty('Background cmd registry is empty!')
        return self.background_cmd_registry[name]

    def clear_registry(self):
        """Removes all entries from registry"""
        self.background_cmd_registry.clear()
